inputs = ['evcug', 'kvaef', 'kucgf', 'dydk', 'zejh']
outputs = ['evcug', 'ievaef', 'ieucgf', 'dyj', 'cejh']

# Let's manually examine the differences
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")
    if inp != outp:
        print(f"  Difference found!")
        # Find where they differ
        for j, (c_in, c_out) in enumerate(zip(inp, outp)):
            if c_in != c_out:
                print(f"  Position {j}: '{c_in}' -> '{c_out}'")
        if len(outp) > len(inp):
            print(f"  Length increased from {len(inp)} to {len(outp)}")
        elif len(outp) < len(inp):
            print(f"  Length decreased from {len(inp)} to {len(outp)}")
    else:
        print(f"  No difference")
    print()

